With c as(Select cu.customer_zip_code_prefix, g.Avg_lat,g.Avg_lng From olist_customer_dataset cuLeft Join geo_less g on cu.customer_zip_code_prefix = g.geolocation_zip_code_prefix),s as (Select se.seller_zip_code_prefix,g.Avg_lat,g.Avg_lng From olist_sellers_dataset seLeft Join geo_less g on se.seller_zip_code_prefix = g.geolocation_zip_code_prefix),i as (Select it.order_id,it.seller_id,c.Avg_lat as customer_lat,c.Avg_lng as customer_lng,s.Avg_lat as seller_lat, s.Avg_lng as seller_lng From olist_orders_dataset oJoin olist_customer_dataset cu on o.customer_id=cu.customer_id Join olist_order_items_dataset it on o.order_id=it.order_idJoin olist_sellers_dataset se on se.seller_id=it.seller_idJoin c on cu.customer_zip_code_prefix=c.customer_zip_code_prefixJoin s on se.seller_zip_code_prefix=s.seller_zip_code_prefix)Select Avg(distance) From ( Select 6371 * ACOS(    COS(RADIANS(i.seller_lat)) * COS(RADIANS(i.customer_lat)) *    COS(RADIANS(i.seller_lng) - RADIANS(i.customer_lng)) +    SIN(RADIANS(i.seller_lat)) * SIN(RADIANS(i.customer_lat))) as distance,    Case when  order_delivered_customer_date> order_estimated_delivery_date Then "Late" Else "On_Time" End  as delivery_flag    From i Join olist_orders_dataset ol on i.order_id=ol.order_id    where order_status='delivered' ) as dis 
group by delivery_flag;